steps.text:
//--- VIOC para_dz: zona de salto de un pedido de jugador = el punto que marco en el mapa (si cae en agua o en la orilla,
//--- el punto de tierra mas cercano a menos de 300 m). [] si no hay tierra cerca: se usa la zona de siempre.
VIOC_fnc_soDZAt = {
	params ["_at"];
	private _p = [_at select 0, _at select 1, 0];
	if ([_p, 40] call VIOC_fnc_soIsLand) exitWith {_p};
	private _res = [];
	{
		private _r = _x;
		for "_a" from 0 to 330 step 30 do {
			private _q = _p getPos [_r, _a];
			if ([_q, 40] call VIOC_fnc_soIsLand) exitWith {_res = [_q select 0, _q select 1, 0]};
		};
		if (count _res > 0) exitWith {};
	} forEach [50, 100, 150, 200, 250, 300];
	_res
};

//--- VIOC para_dz: el paracaidista IA se dirige a su punto de aterrizaje (como quien tira de las lineas del paracaidas):
//--- cada medio segundo, velocidad horizontal hacia el punto = distancia / tiempo de caida que le queda, con tope de
//--- VIOC_SO_STEER m/s. Corrige el viento, la fila del salto y una pasada algo desviada del aparato. Solo donde el
//--- paracaidas es local (el servidor, que lo creo).
VIOC_SO_STEER = 6;
VIOC_fnc_soSteer = {
	params ["_u", "_c", "_aim"];
	private _t = time + 240;
	sleep 1.5;
	while {alive _u && {!isNull _c} && {local _c} && {vehicle _u == _c} && {time < _t}} do {
		private _p = getPosASL _c;
		private _h = if (surfaceIsWater _p) then {_p select 2} else {(getPosATL _c) select 2};
		if (_h < 4) exitWith {};
		private _v = velocity _c;
		private _dx = (_aim select 0) - (_p select 0);
		private _dy = (_aim select 1) - (_p select 1);
		private _d = sqrt ((_dx * _dx) + (_dy * _dy));
		if (_d < 2) then {
			_c setVelocity [0, 0, _v select 2];
		} else {
			private _s = (_d / ((_h / ((abs (_v select 2)) max 1)) max 1)) min VIOC_SO_STEER;
			_c setVelocity [(_dx / _d) * _s, (_dy / _d) * _s, _v select 2];
		};
		sleep 0.5;
	};
};

//--- VIOC para_dz: el punto de paso esta 1,5 km DESPUES de la zona de salto, en la misma linea: el aparato la sobrevuela
//--- recto (con el punto en la zona y radio 200 giraba antes de llegar y la fila caia lejos, en la curva)
private _w1 = _cg addWaypoint [[_dz getPos [1500, _start getDir _dz]] call VIOC_fnc_soClamp, 0];
_w1 setWaypointType "MOVE";
_w1 setWaypointCompletionRadius 300;

private _left = _jumpers select {alive _x && {vehicle _x == _veh}};
private _t2 = time + 60;
private _nj = count _left;	//--- VIOC para_dz: puesto de cada uno en la fila sobre la zona
private _k = 0;

steps.anchor:
if ((_state == "hit") || {!surfaceIsWater (getPosASL _veh)} || {time > (_t2 - 15)}) then {
	private _u = _left deleteAt 0;
	if ([_u, _veh, _op get "chute"] call VIOC_fnc_soJump) then {_jumped = _jumped + 1};

steps.text:
if ((_state == "hit") || {!surfaceIsWater (getPosASL _veh)} || {(_veh distance2D _dz) < 350} || {time > (_t2 - 15)}) then {	//--- VIOC para_dz: cerca de la zona saltan aunque haya agua debajo
	private _u = _left deleteAt 0;
	//--- VIOC para_dz: punto de aterrizaje de cada uno, en fila de 15 m centrada en la zona (no en un salto de emergencia)
	private _aim = if (_state == "hit") then {[]} else {_dz getPos [(_k - ((_nj - 1) / 2)) * 15, _start getDir _dz]};
	if (count _aim > 1 && {surfaceIsWater _aim}) then {_aim = _dz};
	_k = _k + 1;
	if ([_u, _veh, _op get "chute", _aim] call VIOC_fnc_soJump) then {_jumped = _jumped + 1};

//--- VIOC para_dz: los paracaidistas pedidos saltan sobre el punto marcado (o la tierra mas cercana a menos de 300 m)
if (_type == "para" && {count _at > 1}) then {
	private _p = [_at] call VIOC_fnc_soDZAt;
	if (count _p > 0) then {_dz = _p};
};
